	CONSTRAINT fk_planning_scenarios_organization_id_parent_id_plannin_b077 FOREIGN KEY(organization_id, parent_id) REFERENCES planning_scenarios (organization_id, id) ON DELETE RESTRICT, 
	CONSTRAINT fk_planning_scenarios_organization_id_forecast_run_id_f_0b56 FOREIGN KEY(organization_id, forecast_run_id) REFERENCES forecast_runs (organization_id, id) ON DELETE RESTRICT, 
	CONSTRAINT fk_planning_scenarios_organization_id_assumptions_id_pl_bd3b FOREIGN KEY(organization_id, assumptions_id) REFERENCES planning_assumptions (organization_id, id) ON DELETE RESTRICT, 
