	CONSTRAINT fk_planning_comparisons_organization_id_job_id_compute_jobs FOREIGN KEY(organization_id, job_id) REFERENCES compute_jobs (organization_id, job_id) ON DELETE RESTRICT, 
	CONSTRAINT fk_planning_comparisons_organization_id_attempt_id_comp_8aed FOREIGN KEY(organization_id, attempt_id) REFERENCES compute_attempts (organization_id, attempt_id) ON DELETE RESTRICT, 
	CONSTRAINT ck_planning_comparisons_outcome CHECK (outcome IN ('SUCCEEDED', 'PARTIAL')), 
