	CONSTRAINT fk_planning_comparisons_organization_id_organizations FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE RESTRICT, 
	CONSTRAINT uq_planning_comparisons_organization_id_id UNIQUE (organization_id, id), 
	CONSTRAINT uq_planning_comparisons_job_id UNIQUE (job_id), 
	CONSTRAINT uq_planning_comparisons_attempt_id UNIQUE (attempt_id)
)

;

CREATE TABLE planning_method_verifications (
	comparison_id UUID NOT NULL, 
	method TEXT NOT NULL, 
	outcome TEXT NOT NULL, 
	record JSONB NOT NULL, 
	organization_id UUID NOT NULL, 
	id UUID NOT NULL, 
	recorded_at TIMESTAMP WITH TIME ZONE DEFAULT clock_timestamp() NOT NULL, 
	CONSTRAINT pk_planning_method_verifications PRIMARY KEY (id), 
