	CONSTRAINT uq_planning_method_verifications_organization_id_compar_e0b7 UNIQUE (organization_id, comparison_id, method), 
	CONSTRAINT ck_planning_method_verifications_method CHECK (method IN ('CLASSICAL_GP', 'EGP_PI_INSPIRED')), 
	CONSTRAINT fk_planning_method_verifications_organization_id_organizations FOREIGN KEY(organization_id) REFERENCES organizations (id) ON DELETE RESTRICT, 
