)

;
CREATE FUNCTION ppor_immutable_planning() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'planning versions and results are immutable' USING ERRCODE = 'integrity_constraint_violation'; END $$;
CREATE TRIGGER ppor_immutable BEFORE UPDATE OR DELETE ON planning_assumptions FOR EACH ROW EXECUTE FUNCTION ppor_immutable_planning();
CREATE TRIGGER ppor_immutable BEFORE UPDATE OR DELETE ON planning_scenarios FOR EACH ROW EXECUTE FUNCTION ppor_immutable_planning();
CREATE TRIGGER ppor_immutable BEFORE UPDATE OR DELETE ON planning_comparisons FOR EACH ROW EXECUTE FUNCTION ppor_immutable_planning();
CREATE TRIGGER ppor_immutable BEFORE UPDATE OR DELETE ON planning_method_verifications FOR EACH ROW EXECUTE FUNCTION ppor_immutable_planning();
